    this.threshold = const Duration(
      milliseconds: _defaultThresholdMs,
    ),
    this.repeatInterval = const Duration(seconds: 30),
    void Function(String message)? onBreadcrumb,
    Stopwatch? uptime,
  }) : _onBreadcrumb =
