/// The extension-panel relay factory (issue #34 item 1): when this build
/// runs inside the browser extension panel (a `chrome.runtime.id` page),
/// the chat is served by the service-worker agent over the worker relay —
/// the UI holds no keys and gains the SW's browser tools. Null for plain
/// web/desktop, which keeps the local [AgentService.create] path.
///
/// The host is decided by [decideRelay]: the build flag
/// (`--dart-define=FA_HOST=extension`, set by `build_browser_ext.sh
/// --with-app`) wins over the runtime probe, and the decision + reason are
/// ALWAYS logged — a silent fallthrough here once cost a debugging session
/// ("extension panel, but the local web agent answered").
Future<RelayAgentService?> createRelayServiceIfHosted() async {
  final decision = decideRelay(buildHost: kFaBuildHost, probe: isExtensionHost);
  debugPrint('[fah] relay probe: ${decision.reason}');
  if (!decision.hosted) return null;
  final relay = await RelayAgentService.create();
  debugPrint(
    relay == null
        ? '[fah] relay: hosted, but no port channel (SW unreachable?)'
        : '[fah] relay: worker transport created',
  );
  return relay;
}

Future<void> main() => const FaAppBoot(routes: bootAppRoutes).run();

/// The routes stage: mounts [MyApp] and attaches the OpenRouter OAuth
/// listeners. Lives beside [MyApp] — the boot module (issue #483) stays
/// UI-free.
Future<void> bootAppRoutes(
  BootStores stores,
  FirebaseAnalytics? analytics,
) async {
  debugPrint('[fah] starting runApp');
  runApp(
    MyApp(
      env: stores.env,
      registry: stores.registry,
      lastConnectionStore: stores.lastConnection,
      themeController: stores.themeController,
      themePackStore: stores.themePacks,
      onboardingStore: stores.onboarding,
      skillsAccessStore: stores.skillsAccess,
      sessionKeysStore: stores.sessionKeys,
      mediaModelsStore: stores.mediaModels,
      taskModelsStore: stores.taskModels,
      onDeviceConfigStore: stores.onDeviceConfig,
      imagePreviewStore: stores.imagePreviews,
      networkMode: stores.networkMode,
      networkSessions: stores.networkSessions,
      analytics: analytics,
    ),
  );
  // Attach deep-link (mobile) and postMessage (web) listeners for the
  // OpenRouter OAuth callback. This is fire-and-forget: the coordinator
  // singleton forwards codes to any in-flight settings-sheet flow.
  unawaited(attachOpenRouterOAuthLinks());
  _exchangeOpenRouterWebRedirect(stores.sessionKeys);
}

/// On mobile web (iOS Safari / PWA) the popup cannot reliably hand the code
/// back, so OpenRouter redirects to the app URL with `?code=...&state=...`.
/// Exchange it after the first frame and persist the key.
void _exchangeOpenRouterWebRedirect(SessionKeysStore sessionKeys) {
  if (!kIsWeb) return;
  WidgetsBinding.instance.addPostFrameCallback((_) async {
    final key = await completeOpenRouterOAuthFromRedirect();
    if (key != null && key.isNotEmpty) {
      await sessionKeys.set('OPENROUTER_API_KEY', key);
      debugPrint('[Fa] OpenRouter key saved from redirect');
    }
  });
}

