          watchdog.firstFrame();
          expect(breadcrumbs, hasLength(2));
          expect(breadcrumbs.last, contains('first frame landed at'));
          expect(breadcrumbs.last, contains('watchdog had fired 1×'));
        });
      },
    );

    test('install is idempotent — one timer, one breadcrumb stream', () {
      fakeAsync((async) {
        final breadcrumbs = <String>[];
        final watchdog = BootWatchdog(
          threshold: const Duration(seconds: 4),
          repeatInterval: const Duration(seconds: 30),
          onBreadcrumb: breadcrumbs.add,
        );
        watchdog.install();
        watchdog.install();
        async.elapse(const Duration(seconds: 40));
        // Two installs still mean firing #1 then firing #2 — no double arm.
        expect(breadcrumbs, hasLength(2));
      });
    });

    test('the default watchdog installs against the real binding', () {
      // Smoke: install against the test binding and cancel via a frame.
      fakeAsync((async) {
        final breadcrumbs = <String>[];
        final watchdog = BootWatchdog(
          threshold: const Duration(seconds: 4),
          onBreadcrumb: breadcrumbs.add,
        );
        watchdog.install();
        // A frame lands inside the fake-async zone → the postFrameCallback
        // cancels the watchdog before the threshold.
        async.flushTimers();
        WidgetsBinding.instance.scheduleFrame();
        async.flushTimers();
        async.elapse(const Duration(seconds: 30));
        expect(
          breadcrumbs.where((b) => b.contains('not reached')),
          isEmpty,
        );
      });
    });
  });
}
